49	// ---------------------------------------------------------------------------
50	// Tipos de parâmetros e resultado
51	// ---------------------------------------------------------------------------
52	
53	/** Janela de expiração do convite em horas (R8). Default = 48h. */
54	const DEFAULT_INVITE_EXPIRY_HOURS = 48;
55	
56	export interface InviteWorkerToShiftOptions {
57	  /** Horas até o convite expirar (default: 48). */
58	  expiresInHours?: number;
59	  /** Mensagem personalizada para a notificação (opcional). */
60	  message?: string;
61	}
62	
63	export interface InviteWorkerResult {
64	  application: Application | null;
65	  error?: string;
66	  /** true quando já existe um convite pendente (idempotência). */
67	  alreadyInvited?: boolean;
68	}
69	
70	export interface RespondToInviteResult {
71	  success: boolean;
72	  error?: string;
73	}
