457	        .not('invited_by_company_at', 'is', null)
458	        .order('invited_by_company_at', { ascending: false });
459	
460	      if (error) {
461	        logError('shiftInvite.listInvitesByJob', error);
462	        return [];
463	      }
464	
465	      return (data ?? []) as Application[];
466	    } catch (err) {
