1	const CORS_ORIGIN = Deno.env.get('CORS_ORIGIN');
2	const IS_PRODUCTION = Deno.env.get('ASAAS_ENVIRONMENT') === 'production';
3	
4	// In production, CORS_ORIGIN must be set (e.g. https://worki.com.br)
5	// In sandbox/dev, allow all origins for testing
6	const ALLOWED_ORIGIN = CORS_ORIGIN || (IS_PRODUCTION ? '' : '*');
7	
8	if (IS_PRODUCTION && !CORS_ORIGIN) {
9	    console.error('CRITICAL: CORS_ORIGIN must be set in production. All requests will be blocked.');
10	}
11	
12	// Allowlist of origins that may call these functions. Includes the configured
13	// production origin (CORS_ORIGIN, e.g. the Vercel URL) plus local dev origins so
14	// `npm run dev` on localhost:5173 is not blocked by CORS in production.
15	const STATIC_ALLOWED_ORIGINS = [
16	    'http://localhost:5173',
17	    'http://127.0.0.1:5173',
18	    'http://localhost:3000',
19	    'https://worki-opal.vercel.app',
20	];
21	
22	const ALLOWED_ORIGINS = [
23	    ...(CORS_ORIGIN ? [CORS_ORIGIN] : []),
24	    ...STATIC_ALLOWED_ORIGINS,
25	];
26	
27	/**
28	 * Returns CORS headers with the Access-Control-Allow-Origin dynamically
29	 * reflected from the request's Origin header when it is in the allowlist.
30	 * Falls back to the configured ALLOWED_ORIGIN otherwise.
31	 */
32	export function getCorsHeaders(req?: Request) {
33	    const requestOrigin = req?.headers.get('Origin') ?? '';
34	    const origin = ALLOWED_ORIGINS.includes(requestOrigin)
35	        ? requestOrigin
36	        : ALLOWED_ORIGIN;
37	    return {
38	        'Access-Control-Allow-Origin': origin,
39	        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
40	        'Vary': 'Origin',
41	    };
42	}
43	
44	// Backward-compatible static export (no request context). Prefer getCorsHeaders(req).
45	export const corsHeaders = {
46	    'Access-Control-Allow-Origin': ALLOWED_ORIGIN,
47	    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
48	};
49	
50	export const ASAAS_API_URL = Deno.env.get('ASAAS_ENVIRONMENT') === 'production'
51	    ? 'https://api.asaas.com/v3'
52	    : 'https://sandbox.asaas.com/api/v3';
53	
54	export const getAsaasHeaders = (apiKey?: string) => {
55	    const token = apiKey || Deno.env.get('ASAAS_API_KEY');
56	    if (!token) {
57	        throw new Error('ASAAS_API_KEY is not configured');
58	    }
59	    return {
60	        'Content-Type': 'application/json',
61	        'access_token': token,
62	    };
63	};
